    codice := OrdineR2[i];
    IF codice = 99 THEN
        // Ignora tutto ciò che viene dopo
        FOR j := i TO 3 DO
            StartR2[j] := -1;
        END_FOR;
        EXIT;
    ELSIF codice >= 1 AND codice <= 3 THEN
        StartR2[i] := t;
        t := t + DurataR2[i];
    ELSE
        StartR2[i] := -1;
    END_IF;
END_FOR;

